using Essco.Domain.Products;namespace Essco.Application.Products;
public interface IProductRepository{ValueTask<IReadOnlyCollection<Product>>ListAsync(ProductFilter filter,CancellationToken token);ValueTask<IReadOnlyCollection<AutomaticDiscount>>ListDiscountsAsync(CancellationToken token);ValueTask<bool>SaveDiscountAsync(AutomaticDiscount value,bool isNew,CancellationToken token);ValueTask<bool>DeleteDiscountAsync(string productCode,CancellationToken token);ValueTask<IReadOnlyCollection<PriceList>>ListPriceListsAsync(CancellationToken token);ValueTask<int>SavePriceListAsync(PriceList value,bool isNew,CancellationToken token);ValueTask<bool>SetPriceListInactiveAsync(int id,bool inactive,CancellationToken token);}
public sealed class ProductService(IProductRepository repository){public ValueTask<IReadOnlyCollection<Product>>ListAsync(ProductFilter f,CancellationToken t)=>repository.ListAsync(f,t);public ValueTask<IReadOnlyCollection<AutomaticDiscount>>ListDiscountsAsync(CancellationToken t)=>repository.ListDiscountsAsync(t);public async ValueTask<(bool Succeeded,IReadOnlyCollection<string>Errors)>SaveDiscountAsync(AutomaticDiscount x,bool n,CancellationToken t){var e=x.Validate();if(e.Count>0)return(false,e);return await repository.SaveDiscountAsync(x,n,t)?(true,[]):(false,["El descuento ya existe o dejó de estar disponible."]);}public ValueTask<bool>DeleteDiscountAsync(string c,CancellationToken t)=>repository.DeleteDiscountAsync(c.Trim(),t);public ValueTask<IReadOnlyCollection<PriceList>>ListPriceListsAsync(CancellationToken t)=>repository.ListPriceListsAsync(t);public async ValueTask<(bool Succeeded,int Id,string?Error)>SavePriceListAsync(PriceList x,bool n,CancellationToken t){if(string.IsNullOrWhiteSpace(x.Name))return(false,x.Id,"El nombre es obligatorio.");var id=await repository.SavePriceListAsync(x,n,t);return id>0?(true,id,null):(false,x.Id,"La lista ya existe o no está disponible.");}public ValueTask<bool>SetPriceListInactiveAsync(int id,bool inactive,CancellationToken t)=>repository.SetPriceListInactiveAsync(id,inactive,t);}
